def _latest_comments(item, cap: int | None) -> list[dict]:
    comments = list(item.metadata.get("comments", []))
    if cap is None:
        return comments
    if cap <= 0:
        return []
    return comments[-cap:]


def _item_dict_capped(item, comments: int | None = None) -> dict:
    data = _item_dict(item)
